import React, { useEffect, useState } from 'react';
import { Card, Typography, Space, InputNumber, Input, Button, Form, message, Descriptions, Tag, Divider, Table } from 'antd';
import { RobotOutlined, SettingOutlined, HistoryOutlined, SaveOutlined } from '@ant-design/icons';

const { Title, Text } = Typography;

type HistoryItem = { ts: string; metric_key: string; meta?: any };

const PhiSettings: React.FC = () => {
  const [loading, setLoading] = useState<boolean>(true);
  const [saving, setSaving] = useState<boolean>(false);
  const [provider, setProvider] = useState<string>('phi-4');
  const [url, setUrl] = useState<string>('');
  const [timeoutMs, setTimeoutMs] = useState<number>(5000);
  const [maxOut, setMaxOut] = useState<number>(256);
  const [retries, setRetries] = useState<number>(0);
  const [temperature, setTemperature] = useState<number>(0.8);
  const [topP, setTopP] = useState<number>(0.95);
  const [systemPrompt, setSystemPrompt] = useState<string>('');
  const [routingMode, setRoutingMode] = useState<string>('primary_with_aux_failover');
  const [history, setHistory] = useState<HistoryItem[]>([]);

  const load = async () => {
    try {
      setLoading(true);
      const resp = await fetch('/api/phi/settings');
      if (resp.ok) {
        const data = await resp.json();
        if (data.provider) setProvider(String(data.provider));
        if (data.url) setUrl(String(data.url));
        if (data.timeout_ms != null) setTimeoutMs(Number(data.timeout_ms));
        if (data.max_output_tokens != null) setMaxOut(Number(data.max_output_tokens));
        if (data.retries != null) setRetries(Number(data.retries));
        if (data.temperature != null) setTemperature(Number(data.temperature));
        if (data.top_p != null) setTopP(Number(data.top_p));
        if (data.system_prompt != null) setSystemPrompt(String(data.system_prompt));
        if (data.routing_mode) setRoutingMode(String(data.routing_mode));
      }
      // история изменений через admin endpoint recent_metrics
      try {
        const r2 = await fetch('/api/admin/soul/metrics/recent?metric_key=phi_settings_changed&limit=50');
        if (r2.ok) {
          const j2 = await r2.json();
          const items = Array.isArray(j2?.items) ? j2.items : [];
          setHistory(items);
        }
      } catch {}
    } catch {
      message.error('Не удалось загрузить настройки Phi');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const save = async () => {
    try {
      setSaving(true);
      const body = {
        provider,
        url,
        timeout_ms: timeoutMs,
        max_output_tokens: maxOut,
        retries,
        temperature,
        top_p: topP,
        system_prompt: systemPrompt,
        routing_mode: routingMode,
      };
      const resp = await fetch('/api/phi/settings', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      if (!resp.ok) {
        const j = await resp.json().catch(() => ({}));
        throw new Error(j?.detail || `HTTP ${resp.status}`);
      }
      message.success('Настройки Phi‑4 сохранены');
      await load();
    } catch (e: any) {
      message.error(`Ошибка сохранения: ${e?.message || e}`);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div style={{ padding: 16 }}>
      <Space direction="vertical" style={{ width: '100%' }} size={16}>
        <div>
          <Title level={2}><SettingOutlined style={{ marginRight: 8 }} /> Настройки Phi‑4</Title>
          <Text type="secondary">Параметры Aux LLM (локальная ветка Phi‑4) с историей изменений</Text>
        </div>

        <Card loading={loading} title={<Space><RobotOutlined /> <span>Текущие параметры</span></Space>}>
          <Descriptions column={1} size="small" bordered>
            <Descriptions.Item label="Провайдер">{provider} <Tag color="blue">Aux</Tag></Descriptions.Item>
            <Descriptions.Item label="Endpoint URL">{url || '—'}</Descriptions.Item>
          </Descriptions>
          <Divider />
          <Form layout="vertical">
            <Form.Item label="Провайдер">
              <Input value={provider} onChange={(e) => setProvider(e.target.value)} />
            </Form.Item>
            <Form.Item label="Endpoint URL">
              <Input value={url} onChange={(e) => setUrl(e.target.value)} placeholder="http://127.0.0.1:8085/completion" />
            </Form.Item>
            <Form.Item label="Timeout, ms">
              <InputNumber value={timeoutMs} onChange={(v) => setTimeoutMs(Number(v || 0))} min={500} step={100} style={{ width: 160 }} />
            </Form.Item>
            <Form.Item label="Max output tokens">
              <InputNumber value={maxOut} onChange={(v) => setMaxOut(Number(v || 0))} min={1} max={8192} style={{ width: 160 }} />
            </Form.Item>
            <Form.Item label="Retries">
              <InputNumber value={retries} onChange={(v) => setRetries(Number(v || 0))} min={0} max={5} style={{ width: 160 }} />
            </Form.Item>
            <Form.Item label="Temperature">
              <InputNumber value={temperature} onChange={(v) => setTemperature(Number(v || 0))} min={0} max={2} step={0.05} style={{ width: 160 }} />
            </Form.Item>
            <Form.Item label="Top‑p">
              <InputNumber value={topP} onChange={(v) => setTopP(Number(v || 0))} min={0} max={1} step={0.01} style={{ width: 160 }} />
            </Form.Item>
            <Form.Item label="System prompt">
              <Input.TextArea value={systemPrompt} onChange={(e) => setSystemPrompt(e.target.value)} rows={3} />
            </Form.Item>
            <Form.Item label="Routing mode (llm.routing.mode)">
              <Input value={routingMode} onChange={(e) => setRoutingMode(e.target.value)} placeholder="primary_only | primary_with_aux_failover | aux_primary_python_fallback" />
            </Form.Item>
            <Button type="primary" icon={<SaveOutlined />} loading={saving} onClick={save}>Сохранить</Button>
          </Form>
        </Card>

        <Card title={<Space><HistoryOutlined /> <span>История изменений</span></Space>}>
          <Table
            dataSource={history}
            rowKey={(r) => `${r.ts}-${r.metric_key}`}
            size="small"
            pagination={{ pageSize: 10 }}
            columns={[
              { title: 'Время', dataIndex: 'ts', key: 'ts', width: 180 },
              { title: 'Ключ', dataIndex: 'metric_key', key: 'metric_key', width: 180 },
              { title: 'Meta', key: 'meta', render: (r: any) => <pre style={{ whiteSpace: 'pre-wrap' }}>{JSON.stringify(r.meta || {}, null, 2)}</pre> },
            ]}
          />
        </Card>
      </Space>
    </div>
  );
};

export default PhiSettings;
